import { AD_GAMES, AdSession, AdShuffleBag } from './ads-engine.js';
import { AdRenderer } from './ads-render.js';
export class PlayableAds {
  constructor({onRevive,onRestart,announce=()=>{}}){this.onRevive=onRevive;this.onRestart=onRestart;this.announce=announce;this.root=document.getElementById('ad-screen');this.canvas=document.getElementById('ad-canvas');this.skip=document.getElementById('ad-skip');this.renderer=new AdRenderer(this.canvas);this.session=null;this.order=new AdShuffleBag();this.raf=0;this.last=0;this.focused=true;this.pointer=null;this.oldFocus=null;this.skip.addEventListener('click',()=>this.finish());document.getElementById('ad-restart').addEventListener('click',()=>{this.stop();this.onRestart();});
    this.canvas.addEventListener('pointerdown',e=>{if(!this.active)return;e.preventDefault();this.canvas.focus({preventScroll:true});this.pointer={id:e.pointerId,x:e.clientX};this.canvas.setPointerCapture(e.pointerId);this.point(e);});this.canvas.addEventListener('pointermove',e=>{if(this.pointer?.id!==e.pointerId)return;e.preventDefault();if(this.session.kind==='helix')this.session.model.drag((e.clientX-this.pointer.x)/this.renderer.scale);else this.point(e);this.pointer.x=e.clientX;});for(const type of ['pointerup','pointercancel','lostpointercapture'])this.canvas.addEventListener(type,()=>{this.pointer=null;});
    window.addEventListener('keydown',e=>this.key(e,true));window.addEventListener('keyup',e=>this.key(e,false));window.addEventListener('blur',()=>{if(this.active){this.focused=false;this.last=0;this.session.model.keys.clear();this.pointer=null;}});window.addEventListener('focus',()=>{this.focused=true;this.last=0;});document.addEventListener('visibilitychange',()=>{this.last=0;if(document.hidden&&this.active){this.session.model.keys.clear();this.pointer=null;}});window.addEventListener('resize',()=>{if(this.active)this.renderer.resize();});}
  get active(){return !!this.session;}
  start(){if(this.active)return false;const kind=this.order.next(),meta=AD_GAMES.find(g=>g.id===kind);this.session=new AdSession(meta.id);this.oldFocus=document.activeElement;this.root.dataset.kind=meta.id;this.root.classList.remove('ad-enter');this.root.hidden=false;this.root.setAttribute('aria-label',meta.name+' 遊べる架空広告');document.querySelector('.arcade').inert=true;document.body.classList.add('ad-open');document.getElementById('ad-title').textContent=meta.name;document.getElementById('ad-tagline').textContent=meta.tag;document.getElementById('ad-hint').textContent=meta.hint;document.getElementById('ad-keys').textContent=meta.keys;this.canvas.setAttribute('aria-label',meta.hint+' '+meta.keys+'。5秒後からスキップして復活できます');this.focused=true;this.last=0;this.pointer=null;this.readyAnnounced=false;this.renderError=null;this.renderer.lowMotion=document.body.classList.contains('motion-low');this.renderer.resize();this.paint();void this.root.offsetHeight;this.root.classList.add('ad-enter');this.canvas.focus({preventScroll:true});this.announce(meta.name+'。'+meta.hint+' 5秒後にスキップして復活できます');this.raf=requestAnimationFrame(t=>this.frame(t));return true;}
  point(e){if(!this.active||this.session.kind==='helix')return;const r=this.canvas.getBoundingClientRect(),p=this.renderer.world(e.clientX-r.left,e.clientY-r.top);this.session.model.point(p.x,p.z);}
  key(e,down){if(!this.active||e.altKey||e.ctrlKey||e.metaKey)return;if(e.code==='Tab'&&down){const focusable=[this.canvas,...this.root.querySelectorAll('button:not(:disabled)')];let i=focusable.indexOf(document.activeElement);i=e.shiftKey?(i-1+focusable.length)%focusable.length:(i+1)%focusable.length;e.preventDefault();focusable[i].focus();return;}if(e.code==='Escape'&&down){e.preventDefault();if(this.session.ready)this.finish();else this.announce('あと'+this.session.remaining+'秒でスキップできます');return;}const controls=['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','KeyA','KeyD','KeyW','KeyS'];if(controls.includes(e.code)){e.preventDefault();if(down)this.session.model.keys.add(e.code);else this.session.model.keys.delete(e.code);}}
  frame(now){if(!this.active)return;const dt=this.last?Math.max(0,(now-this.last)/1000):0;this.last=now;this.session.update(dt,this.focused&&!document.hidden);this.paint();this.raf=requestAnimationFrame(t=>this.frame(t));}
  paint(){if(!this.active)return;const s=this.session,m=s.model;try{if(!this.renderError)this.renderer.render(s.kind,m);}catch(error){if(!this.renderError){this.renderError=error;this.canvas.dataset.renderer='unavailable';console.error('3D renderer unavailable',error);this.announce('この端末では3Dを表示できません。5秒後にスキップできます');}}this.skip.disabled=!s.ready;this.skip.textContent=s.ready?'スキップして復活 ›':'あと '+s.remaining+' 秒でスキップ';document.getElementById('ad-progress').style.width=Math.min(100,s.elapsed/5*100)+'%';document.getElementById('ad-time-note').textContent=s.ready?'好きなだけ遊べます。戻りたいときにスキップ':'5秒後にスキップ解放 · 成績に関係なく復活';if(s.ready&&!this.readyAnnounced){this.readyAnnounced=true;this.announce('スキップ可能になりました。遊び続けても、スキップして復活しても大丈夫です');}const stats=s.kind==='snow'?[['炉の温度',Math.round(m.heat)+'°'],['暖まった人',m.warm+'/12'],['運んだ薪',m.delivered]]:s.kind==='hole'?[['SIZE','Lv.'+m.level],['飲みこんだ数',m.eaten],['SCORE',m.score]]:[['COMBO',m.charged?'FIRE!':m.streak+'/3'],['落ちた階',m.depth],['SCORE',m.score]];for(let i=0;i<3;i++){document.getElementById('ad-stat-label-'+i).textContent=stats[i][0];document.getElementById('ad-stat-'+i).textContent=stats[i][1];}document.getElementById('ad-game-message').textContent=this.renderError?'3Dを表示できません。スキップして続けられます':m.message;}
  finish(){if(!this.active||!this.session.close())return false;this.stop();this.onRevive();return true;}
  stop(){cancelAnimationFrame(this.raf);this.raf=0;if(this.session)this.session.model.keys.clear();if(this.pointer&&this.canvas.hasPointerCapture(this.pointer.id))this.canvas.releasePointerCapture(this.pointer.id);this.session=null;this.pointer=null;this.last=0;this.renderer.stop?.();this.root.hidden=true;this.root.classList.remove('ad-enter');document.querySelector('.arcade').inert=false;document.body.classList.remove('ad-open');}
}
